// Voor elke draaiende test:
//   - aA = Variant A sessions, cA = Variant A conversions
//   - aB = Variant B sessions, cB = Variant B conversions
//   - CR_A = cA / aA, CR_B = cB / aB
//   - lift = (CR_B - CR_A) / CR_A * 100 (of andersom)
//   - significant = (aA >= 100 AND aB >= 100) AND abs(lift) >= 10
// Return array met { test_id, winner, lift, significant, reason }

const results = [];
for (const item of items) {
  const test = item.json.fields;
  const testId = test['Test ID'];
  const aA = parseInt(test['Variant A Sessions'] || 0);
  const cA = parseInt(test['Variant A Conversions'] || 0);
  const aB = parseInt(test['Variant B Sessions'] || 0);
  const cB = parseInt(test['Variant B Conversions'] || 0);

  const CR_A = aA > 0 ? cA / aA : 0;
  const CR_B = aB > 0 ? cB / aB : 0;

  let winner = 'Inconclusive';
  let lift = 0;
  let significant = false;

  if (aA >= 100 && aB >= 100) {
    if (CR_A > CR_B) {
      lift = CR_B > 0 ? ((CR_A - CR_B) / CR_B) * 100 : 100;
      if (lift >= 10) { winner = 'A'; significant = true; }
    } else if (CR_B > CR_A) {
      lift = CR_A > 0 ? ((CR_B - CR_A) / CR_A) * 100 : 100;
      if (lift >= 10) { winner = 'B'; significant = true; }
    }
  }

  results.push({
    json: {
      test_id: testId,
      test_name: test['Test Name'],
      product: test['Product'],
      winner,
      lift: Math.round(lift * 10) / 10,
      significant,
      CR_A: Math.round(CR_A * 10000) / 100,
      CR_B: Math.round(CR_B * 10000) / 100,
      sessions_A: aA,
      sessions_B: aB,
      reason: significant ? `Variant ${winner} wint met ${lift.toFixed(1)}% lift` : 'Nog niet significant — meer data nodig'
    }
  });
}

return results;
